import sys
from collections import defaultdict

def find_index_to_remove(n, b):
    if n == 2:
        return 1

    freq = defaultdict(int)
    min_val = min(b)
    max_val = max(b)

    for num in b:
        freq[num] += 1

    if len(freq) == 1:
        return 1

    for i in range(n):
        new_min = min_val
        new_max = max_val
        if b[i] == new_min:
            new_min += 1
        elif b[i] == new_max:
            new_max -= 1

        if new_min > new_max:
            continue

        diff = (new_max - new_min) // (n - 2)

        if (new_max - new_min) % (n - 2) != 0:
            continue

        is_arithmetic = True
        current = new_min
        count = 0

        for j in range(n):
            if b[j] == current:
                count += 1
                current += diff
                if count > freq[current]:
                    is_arithmetic = False
                    break
            elif b[j] < current:
                is_arithmetic = False
                break

        if is_arithmetic:
            return i + 1

    return -1

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    b = list(map(int, data[1:]))

    result = find_index_to_remove(n, b)
    print(result)
